class Parent;
class Child {
public:
    std::shared_ptr<Parent> parent_ptr; // Strong back-reference (creates a cycle)
    std::weak_ptr<Parent> weak_parent_ptr; // Non-owning back-reference (breaks cycle)
    ~Child() { std::cout << "Child destroyed\n"; }
};

class Parent {
public:
    std::shared_ptr<Child> child_ptr;
    ~Parent() { std::cout << "Parent destroyed\n"; }
};

void demonstrate_cycle() {
    auto p = std::make_shared<Parent>();
    auto c = std::make_shared<Child>();
    p->child_ptr = c;
    c->parent_ptr = p; // Cycle created, neither destructor will be called
}

void demonstrate_weak_ptr() {
    auto p = std::make_shared<Parent>();
    auto c = std::make_shared<Child>();
    p->child_ptr = c;
    c->weak_parent_ptr = p; // No cycle, both destructors will be called

    // Using the weak pointer requires locking it first
    if (auto locked_parent = c->weak_parent_ptr.lock()) {
        // OK: parent is still alive, we have a temporary shared_ptr
        std::cout << "Child can access parent.\n";
    } else {
        std::cout << "Parent has been destroyed.\n";
    }
}
